def positioning_control() -> dict:
    shares = POSITIONING["shares"]
    known_share = 100 - shares["Não sabe"]
    recomposed = {}
    for candidate in ("Lula", "Flávio"):
        key = "Flávio" if candidate == "Flávio" else candidate
