            "difference_interval_95": [round(first_lead - first_moe, 2), round(first_lead + first_moe, 2)],
            "deff_to_include_zero": round((first_lead / first_moe) ** 2, 2),
            "rho_with_six_per_sector": round((((first_lead / first_moe) ** 2) - 1) / 5, 3),
        },
        "runoff": {
            "lead": 3,
            "difference_moe_95": round(runoff_moe, 2),
            "difference_interval_95": [round(3 - runoff_moe, 2), round(3 + runoff_moe, 2)],
            "statistically_clear_under_srs": False,
