            "sources": source_manifest(),
        },
        "instrument": instrument_payload(),
        "invoices": invoice_payload(),
        "first_round": FIRST_ROUND,
        "runoffs": RUNOFFS,
        "positioning": POSITIONING,
        "positioning_control": positioning_control(),
        "segments": {**SEGMENTS, "Flávio_margin": segment_margins},
        "approval": APPROVAL,
        "conversion_gap": conversion_gaps(),
        "channels": CHANNELS,
        "other_findings": OTHER_FINDINGS,
        "uncertainty": uncertainty_payload(),
        "transfer": transfer_payload(),
        "territory_summary": {
            "rounds": territory["rounds"],
            "comparison": territory["comparison"],
            "ibge_validation": territory["ibge_validation"],
        },
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, default=OUTPUT)
    parser.add_argument("--refresh-ibge", action="store_true")
    args = parser.parse_args()
    payload = build_payload(args.refresh_ibge)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n")
    summary = {
        "output": str(args.output.relative_to(ROOT)),
        "territory_output": str(TERRITORY_OUTPUT.relative_to(ROOT)),
        "first_round": [38, 31],
        "runoff": [43, 40],
        "runoff_srs_interval": payload["uncertainty"]["runoff"]["difference_interval_95"],
        "addressable_gap_region": payload["conversion_gap"]["closed_partitions"]["region"]["addressable_ceiling_gap"],
        "transfer_ratio": payload["transfer"]["outside_base_gain"]["Flávio_to_Lula_ratio"],
        "common_municipalities": payload["territory_summary"]["comparison"]["common_municipalities"],
        "common_exact_sectors": payload["territory_summary"]["comparison"]["common_exact_sectors"],
    }
    print(json.dumps(summary, ensure_ascii=False, indent=2))


