    var items = Object.keys(data.segments["Flávio_margin"]).map(function (name) {
      return [name, data.segments["Flávio_margin"][name]];
    }).sort(function (a, b) { return b[1] - a[1]; });
    var chart = el("div", { class: "rank-chart" });
