import html.parser,sys
class P(html.parser.HTMLParser):
    def __init__(self): super().__init__(); self.stack=[]; self.err=[]
    def handle_starttag(self,tag,attrs):
        if tag not in ('meta','link','br','img','hr','input'): self.stack.append(tag)
    def handle_endtag(self,tag):
        if not self.stack: self.err.append('extra close '+tag); return
        if self.stack[-1]==tag: self.stack.pop()
        else: self.err.append('mismatch %s vs %s'%(tag,self.stack[-1]))
p=P(); p.feed(open('docs/quaest_globo_140826.html').read())
print('unclosed:',p.stack[:10]); print('errors:',p.err[:10])
"; grep -o 'id="[a-z-]*"' docs/quaest_globo_140826.html | sort -u | head -30

